using System.Globalization;
using System.IO;
using System.Text.RegularExpressions;
namespace MRS;
internal sealed record ImportedDmrMap(string Protocol,int Network,int Site,CapCarrier[] Carriers,int Unresolved){public override string ToString()=>$"{Protocol} / Network {Network} / Site {Site} / {Carriers.Length} carriers / {Unresolved} unresolved";}
internal static class SavedChannelImport
{
 internal static ImportedDmrMap[] DsdFrequencies(string path){var groups=new Dictionary<(string,int,int),List<(int Ota,long Hz)>>();foreach(string line in File.ReadLines(path)){if(string.IsNullOrWhiteSpace(line)||line.TrimStart().StartsWith(';'))continue;var f=line.Split(',').Select(x=>x.Trim()).ToArray();if(f.Length<6)throw new IOException("Expected DSDPlus frequency rows with protocol, network, site, OTA channel, TX and RX frequency.");string protocol=f[0] switch{"Con+"=>"Connect Plus","Cap+"=>"Capacity Plus","TIII"=>"DMR Tier III",_=>""};if(protocol=="")continue;if(!int.TryParse(f[1],out int network)||!int.TryParse(f[2],out int site)||!int.TryParse(f[3],out int ota)||ota<=0||!decimal.TryParse(f[4],NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out decimal mhz))throw new IOException("Invalid DSDPlus network/site/channel/frequency. Tier III area.site values require explicit mapping before import.");long hz=(long)(mhz*1000000);if(hz<0||hz>6000000000)throw new IOException("Imported frequency out of range.");var key=(protocol,network,site);if(!groups.TryGetValue(key,out var rows))groups[key]=rows=[];rows.Add((ota,hz));}
 return groups.Select(g=>{var carriers=g.Value.Where(r=>r.Hz>0).GroupBy(r=>g.Key.Item1=="DMR Tier III"?(r.Ota-1)/2:(r.Ota+1)/2).Select(c=>{if(c.Select(r=>r.Hz).Distinct().Count()!=1)throw new IOException("Conflicting frequencies for a carrier; source left unchanged.");return new CapCarrier(c.Key,c.First().Hz,false,"Imported historical; OTA "+string.Join('/',c.Select(r=>r.Ota))+"; "+Path.GetFileName(path));}).ToArray();TrunkFollower.Validate(new("import","import",g.Key.Item1,1,carriers));return new ImportedDmrMap(g.Key.Item1,g.Key.Item2,g.Key.Item3,carriers,g.Value.Count(r=>r.Hz==0));}).ToArray();}
 internal static SiteChannelData[] P25Data(string path){string system="",site="",nac="";var rows=new List<SiteChannelData>();foreach(string raw in File.ReadLines(path)){string line=raw.Trim();var n=Regex.Match(line,@"^Network:\s*([0-9A-Fa-f]+)\.([0-9A-Fa-f]+)");if(n.Success){system=n.Groups[1].Value.ToUpperInvariant()+"-"+n.Groups[2].Value.ToUpperInvariant();site="";}var st=Regex.Match(line,@"^Site:\s*(\d+)\.(\d+)(?:\s+NAC=([0-9A-Fa-f]+))?");if(st.Success){site=$"RFSS {int.Parse(st.Groups[1].Value)} - Site {int.Parse(st.Groups[2].Value)}";nac=st.Groups[3].Value;}var ch=Regex.Match(line,@"^Channel\s+(\d+)-(\d+):\s*([\d.]+)\s*(.*)");if(ch.Success&&system.Length>0&&site.Length>0){if(!decimal.TryParse(ch.Groups[3].Value,NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out var mhz)||mhz<=0||mhz>6000)throw new IOException("Invalid imported P25 frequency.");string id=$"{int.Parse(ch.Groups[1].Value):00}-{int.Parse(ch.Groups[2].Value):0000}";rows.Add(new("P25",["P25",system,site],$"P25:{system}:{site}",(long)(mhz*1000000),id,ch.Groups[4].Value,$"System {system}; {site}; NAC {nac}",null,"Imported historical; "+Path.GetFileName(path),File.GetLastWriteTimeUtc(path)));}}
 return rows.ToArray();}
}
